class Konto {
  #saldo;

  constructor(saldoPoczatkowe) {
    this.#saldo = saldoPoczatkowe;
  }

  wplac(kwota) {
    this.#saldo += this.#sprawdzKwote(kwota);
    return this.#saldo;
  }

  #sprawdzKwote(kwota) {
    // prywatna metoda - dostepna tylko wewnatrz klasy
    if (kwota <= 0) throw new Error("Kwota musi byc dodatnia");
    return kwota;
  }
}

const konto = new Konto(100);
console.log(konto.saldo); // 100 - odczyt przez publiczny getter, DZIALA
