class Konto {
  #saldo = 0;

  wplac(k) {
    this.#saldo += k;
  }

  wyplac(k) {
    if (k > this.#saldo) return false;
    this.#saldo -= k;
    return true;
  }

  get saldo() {
    return this.#saldo;
  }
}

const konto = new Konto();
konto.wplac(100);
console.log(konto.wyplac(30)); // -> true
console.log(konto.wyplac(500)); // -> false
console.log(konto.saldo);      // -> 70
konto.saldo = 999;             // brak settera - zapis ignorowany (tryb luzny)
console.log(konto.saldo);      // -> 70

